SELECT MAX(team_total) AS highest_total
FROM (
    SELECT match_id, inning, SUM(runs_scored + extra_runs) AS team_total
    FROM Deliveries
    WHERE match_id IN (
        SELECT match_id FROM Matches WHERE venue = 'Himachal Pradesh Cricket Association Stadium, Dharamsala'
    )
    GROUP BY match_id, inning
) AS inns_totals;

